#!/usr/bin/env node
/**
 * Generates src/lib/emojiData.ts — the full Unicode emoji set the mobile
 * reaction/composer picker uses (categories + search keywords).
 *
 * Source: the `emoji-picker-react` dataset already present in node_modules
 * (packages/app depends on it for web). It is only READ here; nothing under
 * packages/ or apps/web is modified. The generated file is committed, so a
 * normal build does not run this script.
 *
 *   node scripts/gen-emoji-data.js
 *
 * Emoji newer than Unicode 13.1 are skipped: Android renders an emoji its OS
 * does not know as an empty box, and 13.1 is what Android 12L (API 32) and
 * newer can all draw. Skin-tone variants are omitted (the base emoji is
 * kept) to keep the bundle small.
 */
const fs = require('node:fs');
const path = require('node:path');

const MAX_VERSION = 13.1;
const src = path.resolve(__dirname, '../../../node_modules/emoji-picker-react/src/data/emojis-en.json');
const data = JSON.parse(fs.readFileSync(src, 'utf8'));

const CATEGORIES = [
  ['smileys_people', 'Smileys & People'],
  ['animals_nature', 'Animals & Nature'],
  ['food_drink', 'Food & Drink'],
  ['activities', 'Activities'],
  ['travel_places', 'Travel & Places'],
  ['objects', 'Objects'],
  ['symbols', 'Symbols'],
  ['flags', 'Flags'],
];

const out = CATEGORIES.map(([key, title]) => {
  const items = data.emojis[key]
    .filter((e) => parseFloat(e.a) <= MAX_VERSION)
    .map((e) => {
      const glyph = e.u
        .split('-')
        .map((cp) => String.fromCodePoint(parseInt(cp, 16)))
        .join('');
      const words = [...new Set(e.n.map((n) => n.toLowerCase()))].join(' ');
      return [glyph, words];
    });
  return { key, title, items };
});

const total = out.reduce((n, c) => n + c.items.length, 0);
const body =
  `// GENERATED by scripts/gen-emoji-data.js — do not edit by hand.\n` +
  `// ${total} emoji (Unicode <= ${MAX_VERSION}), categories + search keywords.\n` +
  `export interface EmojiCategory {\n  key: string;\n  title: string;\n  /** [emoji, space-separated lowercase search keywords] */\n  items: readonly (readonly [string, string])[];\n}\n\n` +
  `export const EMOJI_CATEGORIES: readonly EmojiCategory[] = ${JSON.stringify(out)};\n`;
fs.writeFileSync(path.resolve(__dirname, '../src/lib/emojiData.ts'), body);
console.log(`wrote src/lib/emojiData.ts (${total} emoji, ${(body.length / 1024).toFixed(0)} KB)`);
